"""Parse-check the settings-tool JavaScript with the shipped Node runtime.

The settings tool is the one product surface the green gate otherwise never
looks at: `python/cinbase/config/js/config.js` builds every settings dialog by
hand (it loads the fragments of `config.htm`, wires the checkboxes, and decides
what gets saved), and neither the pre-commit hook nor the Windows umbrella
parses it. A SyntaxError there is silent until a user opens a settings dialog.

Each Service also carries a small `config/config.js` that declares
`imeFolderName`, its table list and the items to lock; those are copied from
sibling to sibling, so a broken one breaks one dialog and nothing else.
Third-party bundles under `python/cinbase/config/js/` (jQuery, bootstrap,
TouchSpin, jAlert) are vendored and not ours to lint.

The check runs the bundled `node/node.exe --check`, the same runtime the
umbrella exercises for the Node backend. Where that binary cannot execute
(a Linux CI runner, a machine without the vendored toolchain) the test skips,
matching how the other Windows-only layers report SKIP rather than failing.
"""

import json
import os
import subprocess
import unittest

ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), os.path.pardir))
NODE = os.path.join(ROOT, "node", "node.exe")
CINBASE_CONFIG_JS = os.path.join(ROOT, "python", "cinbase", "config", "js", "config.js")
CHEWING_PHRASE_JS = os.path.join(ROOT, "python", "input_methods", "chewing", "js", "user_phrase.js")
INPUT_METHODS_DIR = os.path.join(ROOT, "python", "input_methods")

TIMEOUT_SECONDS = 60


def service_config_scripts():
    """Every per-Service settings script under python/input_methods/."""
    scripts = []
    if not os.path.isdir(INPUT_METHODS_DIR):
        return scripts
    for name in sorted(os.listdir(INPUT_METHODS_DIR)):
        candidate = os.path.join(INPUT_METHODS_DIR, name, "config", "config.js")
        if os.path.isfile(candidate):
            scripts.append(candidate)
    return scripts


def settings_scripts():
    return [CINBASE_CONFIG_JS, CHEWING_PHRASE_JS] + service_config_scripts()


class SettingsScriptParseTests(unittest.TestCase):

    def _run_check(self, path):
        if not os.path.isfile(NODE):
            self.skipTest("no bundled node/node.exe on this machine")
        try:
            completed = subprocess.run(
                [NODE, "--check", path],
                cwd=ROOT,
                stdout=subprocess.PIPE,
                stderr=subprocess.STDOUT,
                timeout=TIMEOUT_SECONDS,
            )
        except OSError as error:
            self.skipTest("bundled node.exe cannot run here: %s" % error)
        except subprocess.TimeoutExpired:
            self.fail("%s --check %s timed out after %ss" % (NODE, path, TIMEOUT_SECONDS))
        return completed

    def test_settings_scripts_parse(self):
        scripts = settings_scripts()
        self.assertTrue(scripts, "no settings scripts found to check")
        self.assertIn(CINBASE_CONFIG_JS, scripts)
        broken = []
        for path in scripts:
            completed = self._run_check(path)
            if completed.returncode != 0:
                broken.append(
                    "%s\n%s" % (os.path.relpath(path, ROOT).replace("\\", "/"),
                                completed.stdout.decode("utf-8", "replace").strip())
                )
        self.assertEqual([], broken, "settings-tool JavaScript does not parse")

    def test_every_service_with_a_settings_page_has_a_settings_script(self):
        """A config.html without its config.js loads a page whose imeFolderName
        is undefined, so the roster-gated blocks decide nothing."""
        missing = []
        for name in sorted(os.listdir(INPUT_METHODS_DIR)):
            config_dir = os.path.join(INPUT_METHODS_DIR, name, "config")
            if not os.path.isdir(config_dir):
                continue
            has_page = os.path.isfile(os.path.join(config_dir, "config.html"))
            has_script = os.path.isfile(os.path.join(config_dir, "config.js"))
            if has_page and not has_script:
                missing.append(name)
        self.assertEqual([], missing)

    def test_color_controls_save_both_documented_forms(self):
        """The three color controls label the 0xRRGGBB form, so the save loop
        must store it: radix 10 truncates "0x123456" to 0 — the same value as
        the 0 = follow-the-system sentinel — while radix 0 reads it fully.
        The vendored jQuery 1.12.4 isNumeric accepts both forms, so the loop
        reaches parseInt for each."""
        if not os.path.isfile(NODE):
            self.skipTest("no bundled node/node.exe on this machine")
        harness = "\n".join([
            "var src = require('fs').readFileSync(%s, 'utf8');" % json.dumps(
                CINBASE_CONFIG_JS.replace("\\", "/")),
            # Faithful to jquery-1.12.4's isNumeric.
            "function isNumeric(obj) { return !isNaN(parseFloat(obj)) && isFinite(obj); }",
            # config.js touches the DOM at load; these stubs answer exactly
            # the statements that run (isIE, includeScriptFile, loadConfig).
            "var document = {",
            "  getElementsByTagName: function () { return [{ innerText: '' }]; },",
            "  createElement: function () { return { innerHTML: '',",
            "    getElementsByTagName: function () { return []; } }; } };",
            "Object.defineProperty(globalThis, 'navigator', { value:",
            "  { userAgent: 'node', appVersion: 'Trident/7.0' },",
            "  configurable: true, writable: true });",
            "function includeScriptFile() {}",
            "$.get = function (url, cb, type) { };",
            "var inputs = [",
            "  { name: 'candTextColor', type: 'text', value: '0x123456' },",
            "  { name: 'windowBackgroundColor', type: 'text', value: '1193046' },",
            "  { name: 'selKeyColor', type: 'text', value: '0' }",
            "];",
            "var selects = [];",
            "function $(sel) {",
            "  if (typeof sel === 'function') { return; }",
            "  return { each: function (cb) {",
            "    (sel === 'input' ? inputs : selects).forEach(",
            "      function (it, i) { cb(i, it); }); } };",
            "}",
            "$.isNumeric = isNumeric;",
            "eval(src);",
            "updateConfig();",
            "console.log(JSON.stringify({",
            "  radix10: parseInt('0x123456', 10),",
            "  radix0: parseInt('0x123456', 0),",
            "  saved: checjConfig",
            "}));",
        ])
        try:
            completed = subprocess.run(
                [NODE, "-e", harness],
                cwd=ROOT,
                stdout=subprocess.PIPE,
                stderr=subprocess.STDOUT,
                timeout=TIMEOUT_SECONDS,
            )
        except OSError as error:
            self.skipTest("bundled node.exe cannot run here: %s" % error)
        except subprocess.TimeoutExpired:
            self.fail("node -e for the color controls timed out after %ss"
                      % TIMEOUT_SECONDS)
        self.assertEqual(0, completed.returncode,
                         completed.stdout.decode("utf-8", "replace"))
        out = json.loads(completed.stdout.decode("utf-8", "replace"))
        self.assertEqual(0, out["radix10"],
                         "radix-10 parseInt truncates 0x123456 at the x")
        self.assertEqual(1193046, out["radix0"],
                         "radix 0 reads the documented 0xRRGGBB form")
        self.assertEqual(1193046, out["saved"]["candTextColor"],
                         "candTextColor must save the hex form, not 0")
        self.assertEqual(1193046, out["saved"]["windowBackgroundColor"],
                         "windowBackgroundColor must save the decimal form")
        self.assertEqual(0, out["saved"]["selKeyColor"],
                         "selKeyColor keeps the 0 follow-the-system sentinel")


if __name__ == "__main__":
    unittest.main()
